import json,random,subprocess,sys,os,tempfile,itertools
random.seed(5)
d=tempfile.mkdtemp()
def dec(n): return str(random.randint(0,10**n))
book={"currencies":{"EUR":{"cash":"0.05"},"SEK":{"cash":"whole"},"GBP":{"cash":"none"},"X":{"cash":"0.10"},"Y":{"cash":"1"}},"tariffs":{}}
for i in range(6):
    ups=sorted(random.sample(range(10,400),2))
    book["tariffs"][f"t{i}"]={"currency":random.choice(list(book["currencies"])),"vat":random.choice(["0.21","0.055","0.125","0.0725","0"]),
     "standing":random.choice(["0.4110","0.3335","0.0005","0.12345"]),
     "bands":[{"upto":str(ups[0]),"price":random.choice(["0.2","0.1005","0.125","0.0505"])},{"upto":str(ups[1]),"price":"0.205"},{"upto":None,"price":random.choice(["0.31","0.0125"])}]}
json.dump(book,open(d+"/book.json","w"))
os.mkdir(d+"/acc")
for i in range(60):
    segs=[]
    import datetime
    s=datetime.date(2026,3,1); 
    st=[]
    cur=s
    for _ in range(random.randint(0,3)):
        n=random.randint(1,12); st.append({"from":str(cur),"to":str(cur+datetime.timedelta(n-1)),"rate":random.choice(["0.4113","0.005","0.0005","0.3333","-0.0004","0"])}); cur+=datetime.timedelta(n)
    end=cur-datetime.timedelta(1) if st else s+datetime.timedelta(29)
    a={"account":f"A{i}","name":"n","tariff":f"t{random.randrange(6)}","period":{"start":str(s),"end":str(end)},
       "readings":[{"meter":"M","kwh":f"{random.randint(0,500)}.{random.choice(['5','25','125','0','05','005'])}"}],
       "credits":[{"ref":"c","amount":random.choice([-4.25,0.005,1.005,2.675,-0.004,0.1,1e15+0.3,-0.0])} for _ in range(random.randint(0,3))]}
    if st:a["standing"]=st
    json.dump(a,open(f"{d}/acc/a{i:02}.json","w"))
def run(root,args):
    p=subprocess.run([sys.executable,"-m","meterbill",*args],cwd=root,capture_output=True,text=True,env={**os.environ,"PYTHONPATH":root})
    return p.returncode,p.stdout,p.stderr
cmds=[["tariffs"],["batch",d+"/acc"],["batch",d+"/acc","--format","csv"],["batch","/app/samples/accounts"]]
for f in ["text","csv","json"]:
    for i in range(60): cmds.append(["bill",f"{d}/acc/a{i:02}.json","--format",f])
for t in range(6):
    for k in ["0","0.005","1.5","99.995","250.125","412.6","0.0001"]:
        for f in ["text","json"]: cmds.append(["quote",f"t{t}",k,str(random.randint(1,40)),"--format",f])
bad=0
for c in cmds:
    c2=["--tariffs",d+"/book.json"]+c if "/app/samples" not in c[-1] else c
    a=run("/tmp/o",c2); b=run("/app",c2)
    if a!=b: bad+=1; print("DIFF",c,a[2][:200],b[2][:200]) if bad<5 else 0
print(len(cmds),"bad",bad)
